const API='/api';let token=localStorage.getItem('sh_token'),user=JSON.parse(localStorage.getItem('sh_user')||'null'),subjects=[];
const savedTheme=localStorage.getItem('sh_theme')||'light';
document.documentElement.dataset.theme=savedTheme;
const $=x=>document.getElementById(x), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hdr=json=>{let h={};if(json)h['Content-Type']='application/json';if(token)h.Authorization='Bearer '+token;return h};
function assetUrl(v){return /^https?:\/\//i.test(String(v||''))?String(v):'/uploads/'+encodeURIComponent(String(v||''));}
function avatarHTML(u,cls='avatar'){if(u?.profile_pic)return `<img class="${cls}" src="${assetUrl(u.profile_pic)}?v=${Date.now()}" alt="Profile picture">`;return `<div class="${cls}">${esc((u?.name||'?')[0])}</div>`}
function confirmDeleteMaterial(id){$('confirmBody').innerHTML=`<h2>Delete Upload?</h2><p>Are you sure you want to delete this study material? This action cannot be undone.</p><div class="confirm-actions"><button class="btn" onclick="closeConfirm()">No</button><button class="btn-danger" onclick="performDeleteMaterial(${id})">Yes, Delete</button></div>`;$('confirmModal').classList.remove('hidden')}
function closeConfirm(){$('confirmModal').classList.add('hidden')}
async function performDeleteMaterial(id){try{await api('/notes/'+id,{method:'DELETE'});closeConfirm();go(document.querySelector('.nav.active')?.dataset.page||'library')}catch(e){closeConfirm();alert(e.message)}}
async function api(url,opt={}){let r=await fetch(API+url,{...opt,headers:{...hdr(opt.body instanceof FormData?false:true),...(opt.headers||{})}});let d=await r.json().catch(()=>({}));if(r.status===401){logout();throw Error('Login required')}if(!r.ok)throw Error(d.message||'Request failed');return d}
function confirmLogout(){$('confirmBody').innerHTML=`<h2>Log out?</h2><p>Are you sure you want to log out of your StudyHub account?</p><div class="confirm-actions"><button class="btn" onclick="closeConfirm()">No</button><button class="btn-danger" onclick="performLogout()">Yes, Log Out</button></div>`;$('confirmModal').classList.remove('hidden')}
function performLogout(){localStorage.removeItem('sh_token');localStorage.removeItem('sh_user');token=null;user=null;closeConfirm();location.reload()}
function logout(){confirmLogout()}
function loginModal(){showAuth('login')}
function registerModal(){showAuth('register')}
function showAuth(mode='login',message=''){
 $('app').classList.add('hidden');
 $('authPage').classList.remove('hidden');
 $('authPage').innerHTML=`<div class="auth-wrap">
   <section class="auth-brand">
    <img class="auth-logo-image" src="assets/studyhub-logo.png" alt="StudyHub logo"><h1 class="auth-brand-title">StudyHub</h1>
    <p>Connect with your classmates, share reviewers, and study smarter together.</p>
    <div class="auth-points"><span>✓ Share notes and reviewers</span><span>✓ Find materials by subject</span><span>✓ Help classmates with upvotes</span></div>
   </section>
   <section class="auth-card">
    ${mode==='login'?`<h2>Log in to StudyHub</h2><p class="auth-muted">Welcome back! Access your study materials.</p>${message?`<div class="auth-error">${esc(message)}</div>`:''}<form onsubmit="login(event)"><input id="em" type="email" placeholder="Email address" autocomplete="email" required><div class="password-wrap"><input id="pw" type="password" placeholder="Password" autocomplete="current-password" required><button class="password-toggle" type="button" onclick="togglePassword('pw',this)" aria-label="Show password" title="Show password">${eyeIcon(false)}</button></div><button class="auth-submit">Log In</button></form><div class="auth-divider"><span>or</span></div><button class="auth-create" onclick="registerModal()">Create New Account</button><p class="auth-foot">StudyHub is for students to share and discover study resources.</p>`:
    `<h2>Create a new account</h2><p class="auth-muted">It's quick and easy to get started.</p>${message?`<div class="auth-error">${esc(message)}</div>`:''}<form onsubmit="register(event)"><input id="rn" type="text" placeholder="Full name" autocomplete="name" required><input id="re" type="email" placeholder="Email address" autocomplete="email" required><label class="role-choice-label">ACCOUNT TYPE</label><select id="rr" class="role-select"><option value="student">Student</option><option value="teacher">Teacher / Moderator</option></select><p class="auth-role-note">Teachers can review reports, remove rule-breaking materials, and moderate student accounts.</p><div class="password-wrap"><input id="rp" type="password" minlength="6" placeholder="New password" autocomplete="new-password" required><button class="password-toggle" type="button" onclick="togglePassword('rp',this)" aria-label="Show password" title="Show password">${eyeIcon(false)}</button></div><button class="auth-submit">Sign Up</button></form><p class="auth-switch">Already have an account? <button onclick="loginModal()">Log In</button></p>`}
   </section>
 </div>`;
 applyTheme(document.documentElement.dataset.theme||'light');
}
async function login(e){e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;button.textContent='Logging in...';try{let d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('em').value,password:$('pw').value})});token=d.token;user=d.user;localStorage.setItem('sh_token',token);localStorage.setItem('sh_user',JSON.stringify(user));init()}catch(x){button.disabled=false;button.textContent='Log In';showAuth('login',x.message)}}
async function register(e){e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;button.textContent='Creating account...';try{await api('/auth/register',{method:'POST',body:JSON.stringify({name:$('rn').value,email:$('re').value,password:$('rp').value,role:$('rr').value})});showAuth('login','Account created successfully. Please log in.')}catch(x){button.disabled=false;button.textContent='Sign Up';showAuth('register',x.message)}}
function eyeIcon(off=false){return off?`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18"></path><path d="M10.6 10.6a2 2 0 0 0 2.8 2.8"></path><path d="M9.9 4.3A10.8 10.8 0 0 1 12 4c5 0 8.8 4 10 8a11.6 11.6 0 0 1-3.1 5"></path><path d="M6.2 6.2C3.9 7.8 2.6 10.2 2 12c1.2 4 5 8 10 8 1.4 0 2.7-.3 3.8-.8"></path></svg>`:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"></path><circle cx="12" cy="12" r="2.8"></circle></svg>`}
function togglePassword(id,button){const input=$(id);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';button.innerHTML=eyeIcon(!show);button.setAttribute('aria-label',show?'Hide password':'Show password');button.setAttribute('title',show?'Hide password':'Show password')}
function openSubjectModal(selectId='subjectSelect', afterAdd=null){if(!user)return loginModal();$('modalBody').innerHTML=`<div class="subject-modal"><div class="subject-modal-head"><div><span class="eyebrow">STUDYHUB</span><h2>Add New Subject</h2><p class="sub">Create a subject for your study materials.</p></div></div><form id="subjectForm" class="subject-form"><div class="field"><label>SUBJECT NAME</label><input id="newSubjectName" placeholder="e.g. Web Development" required></div><div class="field"><label>SUBJECT CODE</label><input id="newSubjectCode" placeholder="e.g. IT101" maxlength="20" required></div><div id="subjectMsg" class="subject-msg"></div><div class="subject-modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="submit" class="btn-primary">＋ Add Subject</button></div></form></div>`;$('modal').classList.remove('hidden');$('newSubjectName').focus();$('subjectForm').onsubmit=async e=>{e.preventDefault();const msg=$('subjectMsg');const name=$('newSubjectName').value.trim();const code=$('newSubjectCode').value.trim().toUpperCase();if(!name||!code)return;try{msg.className='subject-msg loading';msg.textContent='Adding subject...';const d=await api('/subjects',{method:'POST',body:JSON.stringify({name,code})});await loadSubjects();if(selectId){const select=$(selectId);if(select){select.innerHTML=subjects.map(s=>`<option value="${s.id}">${esc(s.code)} — ${esc(s.name)}</option>`).join('');select.value=d.id}}if(afterAdd){closeModal();afterAdd(d);return;}$('modalBody').innerHTML=`<div class="subject-success"><div class="subject-success-icon">✓</div><span class="eyebrow">STUDYHUB</span><h2>Subject Added</h2><p class="sub">${esc(d.code)} — ${esc(d.name)} was added successfully.</p><div class="subject-success-actions"><button class="btn-primary" onclick="closeModal()">Done</button></div></div>`;}catch(x){msg.className='subject-msg error';msg.textContent=x.message}}}
function addSubjectAndSelect(selectId='subjectSelect'){openSubjectModal(selectId)}
function openDeleteSubjectModal(){if(!user)return loginModal();$('modalBody').innerHTML=`<div class="subject-modal"><div class="subject-modal-head"><div><span class="eyebrow">STUDYHUB</span><h2>Manage Subjects</h2><p class="sub">Any logged-in user can remove a subject that is no longer needed.</p></div></div><div id="deleteSubjectList" class="delete-subject-list"></div><div class="subject-modal-actions"><button type="button" class="btn" onclick="closeModal()">Done</button></div></div>`;$('modal').classList.remove('hidden');renderDeleteSubjectList()}
function renderDeleteSubjectList(){const box=$('deleteSubjectList');if(!box)return;if(!subjects.length){box.innerHTML='<div class="empty">No subjects available.</div>';return}box.innerHTML=subjects.map(s=>`<div class="delete-subject-row"><div><strong>${esc(s.code)}</strong><span>${esc(s.name)}</span></div><button class="btn danger" onclick="deleteSubjectForAll(${s.id},'${esc(s.code)}','${esc(s.name)}')">Delete</button></div>`).join('')}
function deleteSubjectForAll(id,code,name){openConfirm('Delete Subject?',`Delete ${code} — ${name}? This subject can be deleted by any logged-in user, but only if no study materials are using it.`,async()=>{try{await api('/subjects/'+id,{method:'DELETE'});await loadSubjects();closeConfirm();renderDeleteSubjectList();const select=$('subjectSelect');if(select){select.innerHTML=subjects.map(s=>`<option value="${s.id}">${esc(s.code)} — ${esc(s.name)}</option>`).join('')}showModalMessage('Subject Deleted','The subject was deleted successfully.','success')}catch(e){closeConfirm();showModalMessage('Unable to delete subject',e.message,'error')}})}
function manageSubjects(){openDeleteSubjectModal()}
function closeModal(){$('modal').classList.add('hidden')}
function applyTheme(theme){
 document.documentElement.dataset.theme=theme;
 localStorage.setItem('sh_theme',theme);
 updateThemeLogos(theme);
 const btn=document.getElementById('themeToggle');
 if(btn){btn.innerHTML=theme==='dark'?'☀':'☾';btn.title=theme==='dark'?'Switch to light mode':'Switch to dark mode';btn.setAttribute('aria-label',btn.title)}
}
function updateThemeLogos(theme){
 const dark=theme==='dark';
 const logoSrc=dark?'assets/studyhub-logo-dark.png':'assets/studyhub-logo.png';
 const markSrc=dark?'assets/studyhub-mark-dark.png':'assets/studyhub-mark.png';
 document.querySelectorAll('.brand-logo,.auth-logo-image').forEach(img=>{img.src=logoSrc});
 document.querySelectorAll('.brand-mark').forEach(img=>{img.src=markSrc});
}
function toggleTheme(){applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')}

function shell(){ $('headerUser').innerHTML=user?`<div class="header-actions"><button id="themeToggle" class="theme-toggle" onclick="toggleTheme()" aria-label="Switch to dark mode" title="Switch to dark mode">☾</button><div class="user-chip">${avatarHTML(user)}<div><b>${esc(user.name)}</b><small class="user-role">${user.role}</small></div></div></div>`:`<div class="header-actions"><button id="themeToggle" class="theme-toggle" onclick="toggleTheme()" aria-label="Switch to dark mode" title="Switch to dark mode">☾</button><button class="btn" onclick="loginModal()">Log in</button> <button class="btn-primary" onclick="registerModal()">Sign up</button></div>`;applyTheme(document.documentElement.dataset.theme);$('welcome').textContent=user?`Good day, ${user.name}!`:'Welcome to StudyHub';$('adminNav').innerHTML=user?.role==='admin'?'<div class="nav-label" style="margin-top:20px">ADMIN</div><button class="nav" data-page="admin">⚙ <span>Admin Dashboard</span></button>':'';$('teacherNav').innerHTML=['teacher','admin'].includes(user?.role)?'<div class="nav-label" style="margin-top:20px">MODERATION</div><button class="nav" data-page="moderation">🛡 <span>Moderation</span></button>':'';document.querySelectorAll('.nav[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page))}
async function loadSubjects(){subjects=await api('/subjects');}
function noteCard(n){const canDelete=!!user&&(user.role==='admin'||(user.role!=='teacher'&&Number(n.user_id)===Number(user.id)));const fileUrl=n.file_url||assetUrl(n.filename);return `<article class="note"><div class="file">${n.mime_type==='application/pdf'?'PDF':'IMG'}</div><span class="subject">${esc(n.subject_code)} · ${esc(n.subject_name)}</span><h3>${esc(n.title)}</h3><p>${esc(n.description||'No description.')}</p><div class="tags">${(n.tags||'').split(',').filter(x=>x.trim()).map(x=>`<span class="tag">#${esc(x.trim())}</span>`).join('')}</div><div class="note-foot"><small>▲ ${n.upvotes} · ${esc(n.uploader)}</small><div class="actions"><button onclick="preview(${n.id},'${esc(n.filename)}','${esc(n.original_name)}','${esc(n.mime_type)}','${esc(n.title)}','${esc(fileUrl)}')">View</button><button class="btn-ai" onclick="summarizeMaterial(${n.id})">AI Summary</button><button class="up" onclick="upvote(${n.id})">▲</button>${canDelete?`<button class="danger" onclick="confirmDeleteMaterial(${n.id})">Delete</button>`:''}</div></div></article>`}
async function getNotes(q='',subject='',mine=false){let u=`/notes?q=${encodeURIComponent(q)}&subject=${encodeURIComponent(subject)}`+(mine?`&user=${user.id}`:'');return api(u)}
async function dashboard(){let notes=await getNotes();let top=notes.slice(0,3);$('content').innerHTML=`<div class="page"><section class="hero"><div><span class="eyebrow" style="color:#b9e4c9">STUDY SMARTER</span><h2>Your shared study space for notes and exam reviewers.</h2><p>Find useful materials organized by subject, upload your own reviewers, and help classmates by upvoting helpful resources.</p></div><button onclick="go('upload')">＋ Upload Material</button></section><div class="stats"><div class="stat"><small>Study Materials</small><strong>${notes.length}</strong></div><div class="stat"><small>Subjects</small><strong>${subjects.length}</strong></div><div class="stat"><small>Top Upvotes</small><strong>${notes.reduce((a,n)=>a+Number(n.upvotes),0)}</strong></div><div class="stat"><small>Your Uploads</small><strong>${user?(await getNotes('', '', true)).length:0}</strong></div></div><div style="display:flex;justify-content:space-between;align-items:end"><div><span class="eyebrow">POPULAR</span><h2>Recently helpful</h2></div><button class="btn" onclick="go('library')">View library →</button></div><div class="grid">${top.map(noteCard).join('')||'<div class="empty">No materials yet. Upload the first one.</div>'}</div></div>`}
async function library(mine=false){$('content').innerHTML=`<div class="page"><span class="eyebrow">${mine?'YOUR FILES':'ALL MATERIALS'}</span><h2>${mine?'My Materials':'Study Library'}</h2><p class="sub">${mine?'Manage the study materials you uploaded.':'Search notes, reviewers, topics, and subjects.'}</p><div class="toolbar"><input id="sq" placeholder="Search title, topic, tag..." oninput="refreshLibrary(${mine})"><select id="sf" onchange="refreshLibrary(${mine})"><option value="">All subjects</option>${subjects.map(s=>`<option value="${s.id}">${esc(s.code)} — ${esc(s.name)}</option>`).join('')}</select></div><div id="libraryGrid" class="grid"></div></div>`;refreshLibrary(mine)}
async function refreshLibrary(mine){try{let n=await getNotes($('sq')?.value||'',$('sf')?.value||'',mine);$('libraryGrid').innerHTML=n.map(noteCard).join('')||'<div class="empty">No study materials found.</div>'}catch(e){alert(e.message)}}
function upload(){if(!user)return loginModal();$('content').innerHTML=`<div class="page"><span class="eyebrow">SHARE KNOWLEDGE</span><h2>Upload Study Material</h2><p class="sub">Share a PDF or image with your classmates. Maximum file size: 10 MB.</p><form id="uf" class="form"><div class="field"><label>TITLE</label><input name="title" placeholder="e.g. Midterm Reviewer" required></div><div class="field"><label>SUBJECT</label><div class="subject-select-row"><select id="subjectSelect" name="subject_id" required>${subjects.map(s=>`<option value="${s.id}">${esc(s.code)} — ${esc(s.name)}</option>`).join('')}</select><button class="btn" type="button" onclick="addSubjectAndSelect()">＋ Add Subject</button><button class="btn danger" type="button" onclick="manageSubjects()">Delete Subject</button></div></div><div class="field full"><label>DESCRIPTION</label><textarea name="description" placeholder="Describe what this material covers..."></textarea></div><div class="field"><label>TAGS</label><input name="tags" placeholder="Midterms, Chapter 1, SQL"></div><div class="field"><label>FILE</label><input name="file" type="file" accept="application/pdf,image/*,.pdf" required></div><div class="field full"><button class="btn-primary">Upload Material</button></div></form><div id="upmsg"></div></div>`;$('uf').onsubmit=submitUpload}
async function submitUpload(e){
 e.preventDefault();
 const form=e.currentTarget;
 const fileInput=form.querySelector('input[name="file"]');
 const file=fileInput?.files?.[0];
 if(!file){$('upmsg').className='danger';$('upmsg').textContent='Please choose a PDF or image file first.';return}
 const ext=(file.name.split('.').pop()||'').toLowerCase();
 const isPdf=file.type==='application/pdf'||ext==='pdf';
 const isImage=(file.type||'').startsWith('image/')||['jpg','jpeg','png','gif','webp','bmp','tif','tiff','svg','heic','heif','avif'].includes(ext);
 if(!isPdf&&!isImage){$('upmsg').className='danger';$('upmsg').textContent='Only PDF or image files can be uploaded.';return}
 if(file.size>10*1024*1024){$('upmsg').className='danger';$('upmsg').textContent='File is too large. Maximum size is 10 MB.';return}
 const fd=new FormData();
 fd.append('title',form.querySelector('[name="title"]').value);
 fd.append('subject_id',form.querySelector('[name="subject_id"]').value);
 fd.append('description',form.querySelector('[name="description"]').value);
 fd.append('tags',form.querySelector('[name="tags"]').value);
 fd.append('file',file,file.name);
 try{
  console.log('StudyHub upload:', file.name, file.type, file.size, [...fd.keys()]);
  const d=await api('/notes',{method:'POST',body:fd});
  $('upmsg').className='toast';$('upmsg').textContent=d.message;
  form.reset();
 }catch(x){$('upmsg').className='danger';$('upmsg').textContent=x.message}
}
function profile(){if(!user)return loginModal();$('content').innerHTML=`<div class="page"><span class="eyebrow">ACCOUNT</span><h2>My Profile</h2><p class="sub">Edit your account information and profile picture anytime.</p><div class="card profile"><div class="profile-top"><div id="profileAvatar">${avatarHTML(user,'avatar profile-avatar')}</div><div><h3>${esc(user.name)}</h3><div class="sub">${esc(user.email)}</div><span class="badge">${esc(user.role)}</span></div></div><div class="profile-picture-box"><div><strong>Profile Picture</strong><p class="sub">Upload a new image to change your profile picture. Maximum 5 MB.</p></div><div class="profile-picture-actions"><label class="btn upload-pic-btn">Choose Picture<input id="profilePicInput" type="file" accept="image/*" hidden></label>${user.profile_pic?'<button class="btn danger" type="button" onclick="removeProfilePicture()">Remove Picture</button>':''}</div><div id="picMsg"></div></div><hr style="border:0;border-top:1px solid #e2e8e3;margin:25px 0"><form id="profileForm" class="form"><div class="field"><label>NAME</label><input id="pname" value="${esc(user.name)}" required></div><div class="field"><label>EMAIL</label><input id="pemail" type="email" value="${esc(user.email)}" required></div><div class="field full"><label>NEW PASSWORD <span class="sub">(leave blank to keep current password)</span></label><div class="password-wrap"><input id="ppassword" type="password" minlength="6" placeholder="Enter a new password"><button class="password-toggle" type="button" onclick="togglePassword('ppassword',this)" aria-label="Show password" title="Show password">${eyeIcon(false)}</button></div></div><div class="field full"><button class="btn-primary">Save Changes</button></div></form><div id="profileMsg"></div></div></div>`;$('profileForm').onsubmit=saveProfile;$('profilePicInput').onchange=uploadProfilePicture}
async function saveProfile(e){e.preventDefault();const msg=$('profileMsg');try{const d=await api('/auth/me',{method:'PATCH',body:JSON.stringify({name:$('pname').value,email:$('pemail').value,password:$('ppassword').value})});token=d.token;user=d.user;localStorage.setItem('sh_token',token);localStorage.setItem('sh_user',JSON.stringify(user));msg.className='toast';msg.textContent=d.message;shell();setTimeout(()=>profile(),400)}catch(x){msg.className='danger';msg.textContent=x.message}}
async function uploadProfilePicture(){const input=$('profilePicInput'),file=input?.files?.[0],msg=$('picMsg');if(!file)return;if(file.size>5*1024*1024){msg.className='danger';msg.textContent='Profile picture must be 5 MB or smaller.';input.value='';return}const ext=(file.name.split('.').pop()||'').toLowerCase();const isImage=(file.type||'').startsWith('image/')||['jpg','jpeg','png','gif','webp','bmp','tif','tiff','svg','heic','heif','avif'].includes(ext);if(!isImage){msg.className='danger';msg.textContent='Please choose an image file.';input.value='';return}const fd=new FormData();fd.append('profile_pic',file,file.name);try{msg.className='sub';msg.textContent='Uploading...';const d=await api('/auth/profile-picture',{method:'POST',body:fd});token=d.token;user=d.user;localStorage.setItem('sh_token',token);localStorage.setItem('sh_user',JSON.stringify(user));msg.className='toast';msg.textContent=d.message;shell();setTimeout(()=>profile(),500)}catch(e){msg.className='danger';msg.textContent=e.message}finally{input.value=''}}
async function removeProfilePicture(){if(!user?.profile_pic)return;openConfirm(`Remove Profile Picture?`,`Do you want to remove your current profile picture?`,async()=>{try{const d=await api('/auth/profile-picture',{method:'DELETE'});token=d.token;user=d.user;localStorage.setItem('sh_token',token);localStorage.setItem('sh_user',JSON.stringify(user));closeConfirm();shell();profile()}catch(e){closeConfirm();alert(e.message)}})}
function openConfirm(title,text,yesAction){$('confirmBody').innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="confirm-actions"><button class="btn" onclick="closeConfirm()">No</button><button class="btn-danger" id="confirmYes">Yes</button></div>`;$('confirmYes').onclick=yesAction;$('confirmModal').classList.remove('hidden')}

async function messages(){
 if(!user)return loginModal();
 $('content').innerHTML=`<div class="page"><span class="eyebrow">COMMUNICATION</span><h2>Messages</h2><p class="sub">Chat with classmates, teachers, and administrators.</p><div class="chat-layout"><aside class="chat-list card"><div class="chat-list-head"><strong>Conversations</strong><button class="btn" onclick="newChat()">＋ New Chat</button></div><div id="conversationList"><div class="empty">Loading conversations...</div></div></aside><section class="chat-panel card"><div id="chatEmpty" class="chat-empty"><div class="chat-empty-icon">✉</div><h3>Select a conversation</h3><p>Choose a person or start a new chat.</p></div><div id="chatWindow" class="hidden"></div></section></div></div>`;
 await refreshConversations();
}
async function refreshConversations(){try{const rows=await api('/chat/conversations');$('conversationList').innerHTML=rows.length?rows.map(c=>`<button class="conversation" onclick="openChat(${c.id})"><div class="conversation-avatar">${esc((c.name||'?')[0])}</div><div class="conversation-main"><strong>${esc(c.name)}</strong><small>${esc(c.role)} · ${esc(c.last_message|| (c.attachment_name ? '📎 '+c.attachment_name : ''))}</small></div>${Number(c.unread)>0?`<span class="unread">${c.unread}</span>`:''}</button>`).join(''):'<div class="empty">No conversations yet.<br>Click <b>＋ New Chat</b> to start.</div>'}catch(e){$('conversationList').innerHTML=`<div class="danger">${esc(e.message)}</div>`}}
async function newChat(){
 $('modalBody').innerHTML=`<div><div class="subject-modal-head"><div><span class="eyebrow">STUDYHUB CHAT</span><h2>Start New Chat</h2><p class="sub">Find a student, teacher, or admin.</p></div></div><input id="chatSearch" placeholder="Search name or email..." oninput="searchChatUsers()"><div id="chatUsers" class="chat-users"><div class="empty">Type to search.</div></div></div>`;
 $('modal').classList.remove('hidden');$('chatSearch').focus();await searchChatUsers();
}
async function searchChatUsers(){try{const q=$('chatSearch')?.value||'';const rows=await api('/chat/users?q='+encodeURIComponent(q));$('chatUsers').innerHTML=rows.map(u=>`<button class="chat-user-row" onclick="startChat(${u.id})"><div class="conversation-avatar">${esc((u.name||'?')[0])}</div><div><strong>${esc(u.name)}</strong><small>${esc(u.email)} · ${esc(u.role)}</small></div></button>`).join('')||'<div class="empty">No users found.</div>'}catch(e){if($('chatUsers'))$('chatUsers').innerHTML=`<div class="danger">${esc(e.message)}</div>`}}
async function startChat(id){closeModal();await openChat(id)}
async function openChat(id){try{const d=await api('/chat/'+id);$('chatEmpty')?.classList.add('hidden');const w=$('chatWindow');w.classList.remove('hidden');w.innerHTML=`<div class="chat-head"><div class="conversation-avatar">${esc((d.user.name||'?')[0])}</div><div><strong>${esc(d.user.name)}</strong><small>${esc(d.user.email)} · ${esc(d.user.role)}</small></div></div><div id="messageList" class="message-list">${d.messages.map(m=>messageBubble(m)).join('')||'<div class="empty">No messages yet. Say hello.</div>'}</div><form id="chatForm" class="chat-compose" enctype="multipart/form-data"><label class="chat-attach-btn" title="Send picture or PDF">📎<input id="chatFile" type="file" accept="application/pdf,image/png,image/jpeg,image/webp,image/gif" hidden onchange="showChatFileName()"></label><div class="chat-compose-main"><div id="chatFileName" class="chat-file-name"></div><textarea id="chatInput" rows="2" maxlength="2000" placeholder="Write a message..."></textarea></div><button class="btn-primary">Send</button></form>`;$('chatForm').onsubmit=e=>sendMessage(e,id);scrollChat();await refreshConversations()}catch(e){alert(e.message)}}
function messageBubble(m){const mine=Number(m.sender_id)===Number(user.id);const body=m.body?`<div>${esc(m.body).replace(/\n/g,'<br>')}</div>`:'';let attachment='';if(m.attachment_url){const url=assetUrl(m.attachment_url),name=esc(m.attachment_name||'Attachment');if(String(m.attachment_type||'').startsWith('image/'))attachment=`<a class="chat-attachment-image" href="${esc(url)}" target="_blank" rel="noopener"><img src="${esc(url)}" alt="${name}"></a>`;else attachment=`<a class="chat-attachment-file" href="${esc(url)}" target="_blank" rel="noopener">📄 <span>${name}</span></a>`}return `<div class="message-row ${mine?'mine':''}"><div class="message-bubble">${body}${attachment}<small>${new Date(m.created_at).toLocaleString()}</small></div></div>`}
function showChatFileName(){const f=$('chatFile')?.files?.[0],box=$('chatFileName');if(!box)return;box.textContent=f?`📎 ${f.name}`:''}
async function sendMessage(e,id){e.preventDefault();const input=$('chatInput'),file=$('chatFile')?.files?.[0],body=input.value.trim();if(!body&&!file)return;const btn=e.currentTarget.querySelector('button');btn.disabled=true;try{if(file&&file.size>10*1024*1024)throw Error('File must be 10 MB or smaller.');const fd=new FormData();if(body)fd.append('body',body);if(file)fd.append('attachment',file);await api('/chat/'+id,{method:'POST',body:fd});input.value='';if($('chatFile'))$('chatFile').value='';showChatFileName();await openChat(id)}catch(x){alert(x.message)}finally{btn.disabled=false}}
function scrollChat(){const box=$('messageList');if(box)box.scrollTop=box.scrollHeight}
async function moderation(){if(!['teacher','admin'].includes(user?.role))return alert('Teacher or admin access required');const s=await api('/moderation/stats');let u=[];if(user.role==='admin')u=await api('/moderation/users');$('content').innerHTML=`<div class="page"><span class="eyebrow">RULES & SAFETY</span><h2>Moderation Center</h2><p class="sub">Remove accounts or study materials that violate StudyHub rules.</p><div class="stats"><div class="stat"><small>Students</small><strong>${s.students}</strong></div><div class="stat"><small>Teachers</small><strong>${s.teachers}</strong></div><div class="stat"><small>All Materials</small><strong>${s.notes}</strong></div><div class="stat"><small>Your Role</small><strong>${esc(user.role)}</strong></div></div>${user.role==='admin'?`<div class="card"><h3>Student Accounts</h3><p class="sub">Only administrators can remove accounts.</p><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Joined</th><th>Action</th></tr></thead><tbody>${u.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${new Date(x.created_at).toLocaleDateString()}</td><td><button class="btn danger" onclick="moderatorDeleteUser(${x.id},'${esc(x.name)}')">Remove Account</button></td></tr>`).join('')||'<tr><td colspan="4">No student accounts found.</td></tr>'}</tbody></table></div>`:`<div class="card"><h3>Teacher Access</h3><p class="sub">Teachers can review the rules and statistics, but cannot delete accounts or study materials. Account and material removal is available to administrators only.</p></div>`}<div class="card moderation-rules"><h3>StudyHub Rules</h3><ul><li>No harassment, threats, or abusive messages.</li><li>No copyrighted material shared without permission.</li><li>No spam, malware, or misleading study files.</li><li>Use the report/remove tools responsibly.</li></ul></div></div>`}
async function moderatorDeleteUser(id,name){openConfirm('Remove Account?',`Remove ${name}'s student account and its uploaded materials? This cannot be undone.`,async()=>{try{await api('/moderation/users/'+id,{method:'DELETE'});closeConfirm();moderation()}catch(e){closeConfirm();alert(e.message)}})}

async function adminPage(){if(user?.role!=='admin')return alert('Admin access required');let s=await api('/admin/stats'),u=await api('/admin/users');await loadSubjects();$('content').innerHTML=`<div class="page"><span class="eyebrow">ADMINISTRATION</span><h2>Admin Dashboard</h2><p class="sub">Manage StudyHub users, subjects and shared materials.</p><div class="stats"><div class="stat"><small>Users</small><strong>${s.users}</strong></div><div class="stat"><small>Materials</small><strong>${s.notes}</strong></div><div class="stat"><small>Subjects</small><strong>${s.subjects}</strong></div><div class="stat"><small>Total Upvotes</small><strong>${s.votes}</strong></div></div><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h3>Users</h3></div><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Action</th></tr></thead><tbody>${u.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td><span class="badge">${x.role}</span></td><td>${x.id===user.id?'Current account':`<button class="btn" onclick="toggleRole(${x.id},'${x.role}')">${x.role==='admin'?'Make student':x.role==='teacher'?'Make admin':'Make teacher'}</button> <button class="btn danger" onclick="deleteUser(${x.id})">Delete</button>`}</td></tr>`).join('')}</tbody></table></div><div class="card" style="margin-top:15px"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px"><div><h3>Subjects</h3><p class="sub" style="margin:4px 0 0">Add subjects or remove subjects that should no longer be available.</p></div><button class="btn" onclick="addSubject()">＋ Add Subject</button></div><table class="table"><thead><tr><th>Subject</th><th>Code</th><th>Action</th></tr></thead><tbody>${subjects.map(x=>`<tr><td>${esc(x.name)}</td><td><span class="badge">${esc(x.code)}</span></td><td><button class="btn danger" onclick="confirmDeleteSubject(${x.id},'${esc(x.code)}','${esc(x.name)}')">Delete Subject</button></td></tr>`).join('')||'<tr><td colspan="3">No subjects found.</td></tr>'}</tbody></table></div></div>`}
function addSubject(){openSubjectModal(null,()=>adminPage())}
function confirmDeleteSubject(id,code,name){openConfirm('Delete Subject?',`Delete ${code} — ${name}? If materials are using this subject, the subject and those materials may also be removed. This action cannot be undone.`,async()=>{try{await api('/subjects/'+id,{method:'DELETE'});closeConfirm();await loadSubjects();adminPage()}catch(e){closeConfirm();showModalMessage('Unable to delete subject',e.message,'error')}})}
function showModalMessage(title,text,type='success'){const cls=type==='error'?'ai-error':'subject-success';$('modalBody').innerHTML=type==='error'?`<div class="subject-success"><div class="subject-success-icon" style="background:#fff5f4;color:#b42318">!</div><span class="eyebrow">STUDYHUB</span><h2>${esc(title)}</h2><p class="sub">${esc(text)}</p><div class="subject-success-actions"><button class="btn-primary" onclick="closeModal()">Done</button></div></div>`:`<div class="${cls}"><div class="subject-success-icon">✓</div><span class="eyebrow">STUDYHUB</span><h2>${esc(title)}</h2><p class="sub">${esc(text)}</p><div class="subject-success-actions"><button class="btn-primary" onclick="closeModal()">Done</button></div></div>`;$('modal').classList.remove('hidden')}
async function toggleRole(id,role){const next=role==='student'?'teacher':role==='teacher'?'admin':'student';try{await api('/admin/users/'+id+'/role',{method:'PATCH',body:JSON.stringify({role:next})});adminPage()}catch(e){alert(e.message)}}
async function deleteUser(id){if(!confirm('Delete this user and their materials?'))return;try{await api('/admin/users/'+id,{method:'DELETE'});adminPage()}catch(e){alert(e.message)}}
async function upvote(id){if(!user)return loginModal();try{await api('/notes/'+id+'/upvote',{method:'POST'});let p=document.querySelector('.nav.active')?.dataset.page;go(p||'library')}catch(e){alert(e.message)}}
async function deleteMaterial(id){confirmDeleteMaterial(id)}
async function summarizeMaterial(id){
 const modal=$('modal');
 $('modalBody').innerHTML='<div class="ai-box"><div class="ai-top"><div><span class="eyebrow">STUDYHUB AI</span><h2>AI Summary</h2><p class="sub">Analyzing this study material with the private StudyHub AI server.</p></div></div><div class="ai-loading"><div class="ai-spinner"></div><strong>Reading your lesson…</strong><span>This can take a little longer for large PDFs.</span></div></div>';
 modal.classList.remove('hidden');
 try{
  const d=await api('/ai/'+id+'/summarize'+(window._aiRegenerate?'?regenerate=1':''),{method:'POST'}); window._aiRegenerate=false;
  $('modalBody').innerHTML='<div class="ai-box"><div class="ai-top"><div><span class="eyebrow">STUDYHUB AI</span><h2>'+esc(d.title||'AI Summary')+'</h2><p class="sub">Personal study reviewer generated from this material.</p></div></div><div class="ai-result">'+formatAiSummary(d.summary)+'</div><div class="ai-actions"><span class="sub">'+(d.cached?'Saved summary':'New summary generated')+'</span><button class="btn" onclick="window._aiRegenerate=true;summarizeMaterial('+id+')">Regenerate</button></div></div>';
 }catch(e){
  $('modalBody').innerHTML='<div class="ai-box"><div class="ai-top"><div><span class="eyebrow">STUDYHUB AI</span><h2>AI Summary</h2></div></div><div class="ai-error"><strong>AI could not summarize this material.</strong><p>'+esc(e.message)+'</p></div><div class="ai-actions"><button class="btn" onclick="summarizeMaterial('+id+')">Try Again</button></div></div>';
 }
}
function formatAiSummary(text){
 return esc(text||'').replace(/^## (.+)$/gm,'<h3>$1</h3>').replace(/^### (.+)$/gm,'<h4>$1</h4>').replace(/^[-*] (.+)$/gm,'<li>$1</li>').replace(/(<li>.*<\/li>)/gs,'<ul>$1</ul>').replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>');
}
let annotationState={noteId:null,pdfUrl:null,selectedText:'',pageNumber:1,rects:[],color:'yellow',sticker:'dino-green',customStickers:[]};
const DINO_STICKERS={
 'dino-green':'🦖','dino-blue':'🦕','dino-pink':'🦖','dino-sleepy':'😴','dino-happy':'🥰'
};
async function loadAnnotations(noteId){return api('/annotations/note/'+noteId)}
async function loadMyStickers(){try{annotationState.customStickers=await api('/stickers/mine');return annotationState.customStickers}catch(e){annotationState.customStickers=[];return []}}
function stickerEmoji(s){return DINO_STICKERS[s]||'🦖'}
function stickerMarkup(s){if(String(s||'').startsWith('custom:')){const id=Number(String(s).split(':')[1]);const x=annotationState.customStickers.find(v=>Number(v.id)===id);if(x)return `<img class="custom-sticker-img" src="${esc(assetUrl(x.image_url))}" alt="${esc(x.name)}" title="${esc(x.name)}">`}return `<span>${esc(stickerEmoji(s))}</span>`}
function customStickerButtons(){return annotationState.customStickers.map(x=>`<button class="sticker-option custom-sticker-option" data-sticker="custom:${x.id}" onclick="pickDino('custom:${x.id}')" title="${esc(x.name)}">${stickerMarkup('custom:'+x.id)}</button>`).join('')}
function customStickerManager(){return `<div class="custom-sticker-create"><strong>Create your own sticker</strong><p class="sub">Upload a PNG, JPG, WEBP, or GIF and use it on your reviewer.</p><div class="custom-sticker-form"><input id="stickerName" type="text" maxlength="80" placeholder="Sticker name"><input id="stickerFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><button class="btn" type="button" onclick="createPersonalSticker()">Save Sticker</button></div><div id="stickerUploadMsg"></div></div>`}
async function annotationModal(selected='',page=1,rects=[]){
 annotationState.selectedText=selected;annotationState.pageNumber=page;annotationState.rects=rects;
 await loadMyStickers();
 $('modalBody').innerHTML=`<div class="annotation-editor"><span class="eyebrow">REVIEWER TOOL</span><h2>Highlight & Personal Note</h2><p class="sub">Save a private note on the part of the reviewer you want to understand later.</p><div class="annotation-quote">“${esc(selected)}”</div><label>HIGHLIGHT COLOR</label><div class="sticker-picker" id="colorPicker"><button class="sticker-option selected" data-color="yellow" onclick="pickHighlightColor('yellow')">🟨</button><button class="sticker-option" data-color="green" onclick="pickHighlightColor('green')">🟩</button><button class="sticker-option" data-color="blue" onclick="pickHighlightColor('blue')">🟦</button><button class="sticker-option" data-color="pink" onclick="pickHighlightColor('pink')">🩷</button></div><label>REVIEWER STICKER</label><p class="sub">Choose a cute sticker or create your own personal sticker.</p><div class="sticker-picker" id="stickerPicker"><button class="sticker-option selected" data-sticker="dino-green" onclick="pickDino('dino-green')">🦖</button><button class="sticker-option" data-sticker="dino-blue" onclick="pickDino('dino-blue')">🦕</button><button class="sticker-option" data-sticker="dino-pink" onclick="pickDino('dino-pink')">🦖💗</button><button class="sticker-option" data-sticker="dino-sleepy" onclick="pickDino('dino-sleepy')">🦖💤</button><button class="sticker-option" data-sticker="dino-happy" onclick="pickDino('dino-happy')">🦖✨</button>${customStickerButtons()}</div>${customStickerManager()}<label>MY PERSONAL NOTE</label><textarea id="annotationNote" rows="4"></textarea><div class="annotation-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn-ai" onclick="askAIAboutSelection()">Ask AI</button><button class="btn-primary" onclick="saveAnnotation()">Save Highlight & Sticker</button></div><div id="annotationAiResult"></div></div>`;
 $('modal').classList.remove('hidden');
}
function pickHighlightColor(c){annotationState.color=c;document.querySelectorAll('#colorPicker .sticker-option').forEach(x=>x.classList.toggle('selected',x.dataset.color===c))}
function pickDino(s){annotationState.sticker=s;document.querySelectorAll('#stickerPicker .sticker-option').forEach(x=>x.classList.toggle('selected',x.dataset.sticker===s))}
async function createPersonalSticker(){
 const file=$('stickerFile')?.files?.[0],name=$('stickerName')?.value?.trim()||'My Sticker',msg=$('stickerUploadMsg');
 if(!file){if(msg)msg.innerHTML='<div class="ai-error">Please choose an image for your sticker.</div>';return}
 if(file.size>2*1024*1024){if(msg)msg.innerHTML='<div class="ai-error">Sticker image must be 2 MB or smaller.</div>';return}
 const fd=new FormData();fd.append('sticker',file);fd.append('name',name);
 try{if(msg)msg.innerHTML='<div class="ai-loading">Creating your sticker…</div>';const d=await api('/stickers',{method:'POST',body:fd});annotationState.customStickers.unshift(d);annotationState.sticker='custom:'+d.id;const picker=$('stickerPicker');if(picker){const b=document.createElement('button');b.className='sticker-option custom-sticker-option selected';b.dataset.sticker='custom:'+d.id;b.title=d.name;b.onclick=()=>pickDino('custom:'+d.id);b.innerHTML=stickerMarkup('custom:'+d.id);picker.appendChild(b)}document.querySelectorAll('#stickerPicker .sticker-option').forEach(x=>x.classList.toggle('selected',x.dataset.sticker==='custom:'+d.id));if(msg)msg.innerHTML='<div class="success">Sticker created and selected.</div>';}catch(e){if(msg)msg.innerHTML='<div class="ai-error">'+esc(e.message)+'</div>'}
}
async function saveAnnotation(){try{const d=await api('/annotations',{method:'POST',body:JSON.stringify({note_id:annotationState.noteId,page_number:annotationState.pageNumber,selected_text:annotationState.selectedText,note_text:$('annotationNote')?.value||'',highlight_color:annotationState.color,sticker:annotationState.sticker,position_data:annotationState.rects})});closeModal();await openPdfReviewer(annotationState.noteId,annotationState.pdfUrl);return d}catch(e){const box=$('annotationAiResult');if(box)box.innerHTML='<div class="ai-error">'+esc(e.message)+'</div>'}}
async function askAIAboutSelection(){const box=$('annotationAiResult');if(!box)return;box.innerHTML='<div class="ai-loading"><div class="ai-spinner"></div><strong>StudyHub AI is explaining this part…</strong></div>';try{const d=await api('/ai/explain',{method:'POST',body:JSON.stringify({text:annotationState.selectedText})});box.innerHTML='<div class="ai-result"><strong>Simple explanation</strong><p>'+esc(d.explanation).replace(/\n/g,'<br>')+'</p></div>'}catch(e){box.innerHTML='<div class="ai-error">'+esc(e.message)+'</div>'}}
async function openPdfReviewer(noteId,url){
 annotationState.noteId=noteId;annotationState.pdfUrl=url;await loadMyStickers(); $('modalBody').innerHTML=`<div class="reviewer-view"><div class="preview-head"><div class="preview-icon">PDF</div><div class="preview-title-wrap"><span class="eyebrow">STUDY REVIEWER</span><h2>Highlight what you don't understand</h2><p class="preview-filename">Select text to highlight it, add a private note, place a dinosaur sticker, or ask AI.</p></div></div><div class="reviewer-toolbar"><span class="hint">Your highlights, notes and stickers are private to your account.</span><button class="btn" onclick="showMyAnnotations()">📝 My Highlights</button><button class="btn" id="expandReviewerBtn" onclick="toggleReviewerExpand()">⛶ Expand</button><a class="btn-primary" href="${esc(url)}" target="_blank" rel="noopener">Open PDF ↗</a></div><div id="pdfReader" class="pdf-reader"><div class="ai-loading"><div class="ai-spinner"></div><strong>Loading reviewer…</strong></div></div></div>`;$('modal').classList.remove('hidden');await renderPdfReviewer(url,noteId)
}
async function renderPdfReviewer(url,noteId){
 const reader=$('pdfReader');
 if(!window.pdfjsLib){reader.innerHTML='<div class="ai-error">PDF reviewer tools could not load. Please check your internet connection and reload StudyHub.</div>';return}
 pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
 try{const pdf=await pdfjsLib.getDocument(url).promise;reader.innerHTML='';const annotations=await loadAnnotations(noteId);
  for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n);const baseViewport=page.getViewport({scale:1});const available=Math.max(360,reader.clientWidth-48);const scale=Math.min(1.25,available/baseViewport.width);const viewport=page.getViewport({scale});const wrap=document.createElement('div');wrap.className='pdf-page';wrap.dataset.page=n;wrap.style.width=viewport.width+'px';wrap.style.height=viewport.height+'px';const canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;wrap.appendChild(canvas);const layer=document.createElement('div');layer.className='pdf-text-layer';layer.style.width=viewport.width+'px';layer.style.height=viewport.height+'px';wrap.appendChild(layer);reader.appendChild(wrap);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const tc=await page.getTextContent();const divs=[];await pdfjsLib.renderTextLayer({textContent:tc,container:layer,viewport,textDivs:divs}).promise;layer.addEventListener('mouseup',()=>handlePdfSelection(wrap));}
  renderSavedAnnotations(annotations); 
 }catch(e){reader.innerHTML='<div class="ai-error"><strong>Could not open the reviewer.</strong><p>'+esc(e.message)+'</p></div>'}
}
function handlePdfSelection(pageEl){setTimeout(()=>{const sel=window.getSelection();const text=sel?.toString().trim();if(!text)return;const range=sel.rangeCount?sel.getRangeAt(0):null;if(!range)return;let layer=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer.closest?.('.pdf-text-layer'):range.commonAncestorContainer.parentElement?.closest?.('.pdf-text-layer');if(!layer)return;const pageRect=pageEl.getBoundingClientRect();const rects=[...range.getClientRects()].map(r=>({x:r.left-pageRect.left+pageEl.scrollLeft,y:r.top-pageRect.top+pageEl.scrollTop,w:r.width,h:r.height})).filter(r=>r.w>1&&r.h>1);if(!rects.length)return;const page=Number(pageEl.dataset.page);annotationState.noteId=annotationState.noteId;showSelectionPopover(text,page,rects,Math.min(window.innerWidth-260,Math.max(10,rects[0].x+pageRect.left)),Math.max(10,rects[0].y+pageRect.top-52));},0)}
function showSelectionPopover(text,page,rects,x,y){document.querySelector('.selection-popover')?.remove();const pop=document.createElement('div');pop.className='selection-popover';pop.style.left=x+'px';pop.style.top=y+'px';pop.innerHTML='<button onclick="openSelectedAnnotation()">🟨 Highlight + Note</button>';document.body.appendChild(pop);annotationState.selectedText=text;annotationState.pageNumber=page;annotationState.rects=rects;pop.dataset.ready='1';}
function openSelectedAnnotation(){document.querySelector('.selection-popover')?.remove();annotationModal(annotationState.selectedText,annotationState.pageNumber,annotationState.rects)}
async function askSelectedAI(){document.querySelector('.selection-popover')?.remove();annotationModal(annotationState.selectedText,annotationState.pageNumber,annotationState.rects);setTimeout(()=>askAIAboutSelection(),50)}
function renderSavedAnnotations(rows){rows.forEach(a=>{const page=document.querySelector(`.pdf-page[data-page="${a.page_number}"]`);if(!page)return;let rects=[];try{rects=typeof a.position_data==='string'?JSON.parse(a.position_data||'[]'):(a.position_data||[])}catch{};rects.forEach(r=>{const el=document.createElement('div');el.className='saved-highlight highlight-'+(a.highlight_color||'yellow');el.style.left=r.x+'px';el.style.top=r.y+'px';el.style.width=r.w+'px';el.style.height=r.h+'px';page.appendChild(el)});if(rects[0]){const st=document.createElement('div');st.className='saved-sticker';st.title=a.note_text||a.selected_text;st.innerHTML=stickerMarkup(a.sticker);st.style.left=Math.min(page.clientWidth-48,Math.max(0,rects[0].x+rects[0].w+5))+'px';st.style.top=Math.max(0,rects[0].y-7)+'px';st.onclick=()=>showAnnotationDetail(a);page.appendChild(st)}})}
function showAnnotationDetail(a){$('modalBody').innerHTML=`<div class="annotation-editor"><span class="eyebrow">MY REVIEWER NOTE</span><h2 class="annotation-sticker-title">${stickerMarkup(a.sticker)} Highlighted section</h2><div class="annotation-quote">“${esc(a.selected_text)}”</div><div class="annotation-card"><strong>My note</strong><p class="note-text">${esc(a.note_text||'No personal note added.')}</p></div><div class="annotation-actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn danger" onclick="deleteAnnotation(${a.id})">Delete</button></div></div>`}
async function deleteAnnotation(id){try{await api('/annotations/'+id,{method:'DELETE'});await openPdfReviewer(annotationState.noteId,annotationState.pdfUrl)}catch(e){alert(e.message)}}
async function showMyAnnotations(){try{await loadMyStickers();const rows=await loadAnnotations(annotationState.noteId);$('modalBody').innerHTML=`<div class="annotation-editor"><span class="eyebrow">MY HIGHLIGHTS</span><h2>Personal notes on this reviewer</h2><p class="sub">Only you can see these highlights, notes and stickers.</p><div class="annotation-list">${rows.length?rows.map(a=>`<div class="annotation-card"><div class="quote"><span class="list-sticker">${stickerMarkup(a.sticker)}</span> Page ${a.page_number}: “${esc(a.selected_text)}”</div><div class="note-text">${esc(a.note_text||'No note added.')}</div><div class="annotation-actions"><button class="btn" onclick="openPdfReviewer(${annotationState.noteId},'${esc(annotationState.pdfUrl)}')">View</button><button class="btn danger" onclick="deleteAnnotation(${a.id})">Delete</button></div></div>`).join(''):'<div class="empty">You have no highlights yet. Select text in the reviewer to create one.</div>'}</div><div class="subject-modal-actions"><button class="btn" onclick="openPdfReviewer(${annotationState.noteId},'${esc(annotationState.pdfUrl)}')">Back to Reviewer</button></div></div>`;$('modal').classList.remove('hidden')}catch(e){alert(e.message)}}

async function toggleReviewerExpand(){
 const reader=document.getElementById('pdfReader');
 if(!reader)return;
 const expanded=reader.classList.toggle('reviewer-reader-expanded');
 const btn=document.getElementById('expandReviewerBtn');
 if(btn)btn.innerHTML=expanded?'⛶ Normal View':'⛶ Expand';
 // Expand ONLY the PDF reading area. Keep the StudyHub modal/header/toolbar normal.
 reader.style.height=expanded?'min(78vh,900px)':'min(58vh,680px)';
}

function preview(id,file,name,mime,title,url){const isImage=mime.startsWith('image/');url=url||assetUrl(file);if(!isImage){openPdfReviewer(id,url);return}const typeLabel='IMAGE';$('modalBody').innerHTML=`<div class="preview-head"><div class="preview-icon">IMG</div><div class="preview-title-wrap"><h2>${esc(title||'Study Material')}</h2><p class="preview-filename" title="${esc(name)}">${esc(name)}</p></div></div><div class="preview-meta"><span>${typeLabel}</span><span>Study Material</span></div><div class="preview-content image-preview"><img src="${esc(url)}" alt="${esc(title||name)}"></div><div class="reviewer-toolbar"><span class="hint">For PDF reviewers, select text to highlight and add a dinosaur sticker.</span><button class="btn-ai preview-ai" onclick="summarizeMaterial(${id})">AI Summary</button><a class="btn-primary preview-open" href="${esc(url)}" target="_blank" rel="noopener">Open original file ↗</a></div>`;$('modal').classList.remove('hidden')}
function go(page){document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('pageName').textContent=({dashboard:'Dashboard',library:'Study Library',upload:'Upload Material',mine:'My Materials',messages:'Messages',profile:'My Profile',admin:'Admin Dashboard',moderation:'Moderation'})[page]||'Dashboard';({dashboard,library,upload,mine:()=>library(true),messages,profile,admin:adminPage,moderation})[page]()}
async function init(){try{if(!user){showAuth('login');return}$('authPage').classList.add('hidden');$('app').classList.remove('hidden');await loadSubjects();shell();go('dashboard')}catch(e){console.error(e)}}
$('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});init();